+// Filter location-owned records while retaining shared records and writes.
+function siteStore(store, site) {
+  const belongs = (location) => store.data.locations.some((l) => l.id === location && l.site === site);
+  const filters = {
+    locations: (l) => l.site === site,
+    batches: (b) => belongs(b.location),
+    stocktakes: (s) => belongs(s.location),
+    temperatures: (t) => belongs(t.location),
+    movements: (m) => store.data.batches.some((b) => b.id === m.batchId && belongs(b.location)),
+  };
+  const data = new Proxy(store.data, {
+    get(target, key) {
+      if (!(key in filters) || !target[key]) return target[key];
+      const source = target[key];
+      const visible = source.filter(filters[key]);
+      Object.defineProperty(visible, "push", { value: (...values) => source.push(...values) });
+      return visible;
+    },
+  });
+  return { data, nextId: store.nextId.bind(store), save: store.save.bind(store) };
+}
